// Execution order quiz — trace through this carefully

console.log('1: sync start');

setTimeout(() => console.log('7: macrotask (setTimeout 0)'), 0);

Promise.resolve()
  .then(() => {
    console.log('3: microtask — Promise.then #1');
    // A microtask enqueued from inside a microtask:
    Promise.resolve().then(() => console.log('5: microtask — nested .then'));
  })
  .then(() => console.log('6: microtask — Promise.then chained'));

queueMicrotask(() => console.log('4: microtask — queueMicrotask'));

console.log('2: sync end');

// Output:
// 1: sync start
// 2: sync end
// 3: microtask — Promise.then #1        (first microtask drained)
// 4: microtask — queueMicrotask         (second microtask)
// 5: microtask — nested .then           (enqueued during #1, still drained before macrotask)
// 6: microtask — Promise.then chained   (third microtask)
// 7: macrotask (setTimeout 0)           (only now, after ALL microtasks)

// Key observations:
// - Both sync lines run before any async callback
// - queueMicrotask fires before the chained .then because it was registered first
// - The nested Promise.resolve().then fires before the chained .then
//   because it was enqueued to the microtask queue while that queue was draining
// - setTimeout 0 fires LAST despite being registered before the Promises

